import { path, type FileSystem } from '@servicenow/sdk-build-core'
import type { Project } from '../../project'
import { IndexBuilder, IndexGenerator, scanForNowFiles, type FileInfo } from './fluent-index-builder'
import { generateTablesGlobalDeclaration } from './tables-global-generator'

// Re-export FileInfo for backwards compatibility
export type { FileInfo } from './fluent-index-builder'

/**
 * Generates index.ts files for fluent types (.d.now.ts files)
 * Orchestrates: scan → group → generate
 */
export async function generateFluentIndexes(project: Project): Promise<void> {
    const fs = project.getFileSystem()
    const fluentTypeDir = project.resolvePath(project.getConfig().typesDir, 'fluent')

    // 1. Scan for all .d.now.ts files (new + existing) - simple recursion
    const allFiles = scanForNowFiles(fs, fluentTypeDir)

    // 2. Group files by their index directory
    const builder = new IndexBuilder()
    const filesByDirectory = builder.groupFilesByDirectory(allFiles, fluentTypeDir)

    // 3. Generate index file for each directory using ts-morph
    const generator = new IndexGenerator(fs, project)
    for (const [dirPath, files] of filesByDirectory.entries()) {
        const config = builder.buildIndexConfig(dirPath, files)
        generator.generateIndexFile(dirPath, config)
    }

    // 4. Generate parent index files
    generateParentIndexFiles(fs, project, fluentTypeDir, filesByDirectory)

    // 5. Generate tables.d.ts global declaration (for core/tables only)
    await generateTablesGlobalDeclaration(project)
}

/**
 * Generates parent index files for all directory hierarchies
 * Creates index.ts files that re-export from subdirectories
 */
function generateParentIndexFiles(
    fs: FileSystem,
    project: Project,
    fluentTypeDir: string,
    filesByDirectory: Map<string, FileInfo[]>
): void {
    // Collect all unique parent directories
    const parentDirs = new Map<string, Set<string>>()

    for (const dirPath of filesByDirectory.keys()) {
        const relativePath = path.relative(fluentTypeDir, dirPath)
        const pathParts = relativePath.split(path.sep)

        // For each level in the hierarchy, track subdirectories
        for (let i = 0; i < pathParts.length; i++) {
            const parentPath = i === 0 ? fluentTypeDir : path.join(fluentTypeDir, ...pathParts.slice(0, i))
            const childDirName = pathParts[i]

            if (!parentDirs.has(parentPath)) {
                parentDirs.set(parentPath, new Set())
            }
            const subdirSet = parentDirs.get(parentPath)
            if (subdirSet && childDirName) {
                subdirSet.add(childDirName)
            }
        }
    }
    const logger = project.getLogger()
    // Generate index file for each parent directory (except root)
    for (const [parentPath, subdirs] of parentDirs.entries()) {
        const relativePath = path.relative(fluentTypeDir, parentPath)

        // Skip root fluent directory - users import from subdirectories like #now:automation
        if (relativePath === '') {
            continue
        }

        const indexPath = path.join(parentPath, 'index.ts')
        const level = relativePath

        // Re-export everything from each subdirectory
        // Subdirectories export direct categories (e.g., role, table, view)
        const exports = Array.from(subdirs)
            .sort()
            .map((dirName) => `export * from './${dirName}'`)

        const content = `/**
 * Fluent Types - ${level} Index
 *
 * Auto-generated - re-exports from subdirectories.
 */

${exports.join('\n')}
`

        fs.writeFileSync(indexPath, content, { encoding: 'utf-8' })
        logger.debug(`Generated parent index: ${indexPath}`)
    }
    logger.debug(`Generated ${parentDirs.size} parent index file(s)`)
}
